// Şu anki zaman referansı
const now = new Date();

// Sadece uyarı verilecek darboğaz görevlerini tutacağımız liste
const bottleneckItems = [];

// Önceliklerin (Priority) katsayıları
const priorityWeights = {
  "low": 1,
  "medium": 1.5,
  "high": 2,
  "Critical": 3
};

for (const item of $input.all()) {
  const data = item.json;

  // Notion'dan gelen veriler (Property isimleri görselindeki gibi güncellendi)
  const lastUpdatedStr = data.property_last_updated_raw?.start;
  const deadlineStr = data.property_deadline_raw?.start || data.property_deadline?.start; 
  const status = data.property_status;
  const priority = data.property_priority;

  // Eğer tarih verileri boşsa bu görevi atla
  if (!lastUpdatedStr || !deadlineStr) continue;

  const lastUpdated = new Date(lastUpdatedStr);
  const deadline = new Date(deadlineStr);

  // 1. Bekleme Süresi (Waiting Hours) Hesaplama
  const waitingMs = now.getTime() - lastUpdated.getTime();
  const waitingHours = Math.max(0, Math.floor(waitingMs / (1000 * 60 * 60)));

  // 2. Gecikme Gün Sayısı (Overdue Days) Hesaplama
  const overdueMs = now.getTime() - deadline.getTime();
  const overdueDays = Math.max(0, Math.floor(overdueMs / (1000 * 60 * 60 * 24)));

  // 3. BOTTLENECK SCORE (Darboğaz Skoru) Hesaplama
  let score = 0;

  // A) Durum Puanı: "Stuck" olanlar anında alarm sebebidir
  if (status === "Stuck") score += 30;
  else if (status === "in progress") score += 10;

  // B) Zaman Puanları: Her 10 saat bekleme 1 puan, her gecikme günü 5 puan ekler
  score += Math.floor(waitingHours / 10); 
  score += (overdueDays * 5); 

  // C) Öncelik Çarpanı: Çıkan ham skor, görevin önceliği ile çarpılır
  const pWeight = priorityWeights[priority] || 1;
  score = Math.floor(score * pWeight); 

  // 4. RISK LEVEL (Risk Seviyesi) Belirleme
  let riskLevel = "None";
  if (score >= 80) riskLevel = "Critical";
  else if (score >= 50) riskLevel = "High";
  else if (score >= 25) riskLevel = "Medium";
  else if (score > 0) riskLevel = "Low";

  // Hesaplanan verileri JSON içerisine ekliyoruz
  data["calculated_waiting_hours"] = waitingHours;
  data["calculated_overdue_days"] = overdueDays;
  data["calculated_bottleneck_score"] = score;
  data["calculated_risk_level"] = riskLevel;

  // 5. FİLTRELEME: Sadece 'High' ve 'Critical' seviyedeki tıkanıklıkları uyarılara gönder
  if (riskLevel === "Critical" || riskLevel === "High") {

    // E-posta adımında kullanılacak özet metin
    data.alert_summary = `🚨 Tıkanıklık: [${data.property_department}] departmanında ${data.property_owner} sorumluluğundaki "${data.property_stage}" aşaması! Skor: ${score} | ${overdueDays > 0 ? overdueDays + ' gün gecikti' : 'Gecikme yok ama uzun süredir beklemede'}.`;

    bottleneckItems.push(item);
  }
}

// Sonraki node'a sadece darboğaz yaratan riskli işler gider
return bottleneckItems;
